package main

import (
	"encoding/json"
	"log"
	"os"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

func main() {
	n := maelstrom.NewNode()

	// Handle "echo" requests: reply with an "echo_ok" that carries the same
	// echo value back to the client. The echo value may be any JSON value,
	// so keep it as raw JSON to round-trip it exactly.
	n.Handle("echo", func(msg maelstrom.Message) error {
		var req map[string]json.RawMessage
		if err := json.Unmarshal(msg.Body, &req); err != nil {
			return err
		}

		body := map[string]any{"type": "echo_ok"}
		if raw, ok := req["echo"]; ok {
			body["echo"] = raw
		}

		return n.Reply(msg, body)
	})

	if err := n.Run(); err != nil {
		log.Printf("node error: %v", err)
		os.Exit(1)
	}
}

